"""Column helpers shared by every model (DB-03, DB-04)."""
import uuid

from sqlalchemy import Uuid

from ..extensions import db


def uuid_pk():
    """UUID primary key generated by the application, never accepted from a client."""
    return db.Column(Uuid(as_uuid=True), primary_key=True, default=uuid.uuid4)


def uuid_fk(target, nullable=False, ondelete=None, index=False):
    return db.Column(Uuid(as_uuid=True), db.ForeignKey(target, ondelete=ondelete), nullable=nullable, index=index)


def timestamp(nullable=False):
    """Timezone-aware UTC timestamp. The service sets it from the injected clock."""
    return db.Column(db.DateTime(timezone=True), nullable=nullable)